CREATE FUNCTION public.rota_my_work_context(t uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE e public.hr_employees;today date:=(now() AT TIME ZONE 'Asia/Hong_Kong')::date;BEGIN
IF NOT public.user_has_tenant(auth.uid(),t) OR EXISTS(SELECT 1 FROM public.user_access_control WHERE tenant_id=t AND user_id=auth.uid() AND status='disabled') THEN RAISE EXCEPTION 'Staff sign-in required';END IF;
IF (SELECT count(*) FROM public.hr_employees WHERE tenant_id=t AND user_id=auth.uid() AND status IN('active','on_leave'))<>1 THEN RAISE EXCEPTION 'One linked person required';END IF;SELECT * INTO e FROM public.hr_employees WHERE tenant_id=t AND user_id=auth.uid() AND status IN('active','on_leave');
RETURN jsonb_build_object('person',to_jsonb(e),'today',today,'shifts',COALESCE((SELECT jsonb_agg(to_jsonb(s)||jsonb_build_object('settlement',CASE WHEN z.source_updated_at=s.updated_at THEN to_jsonb(z) END)) FROM public.hr_shifts s LEFT JOIN public.hr_shift_settlements z ON z.shift_id=s.id WHERE s.tenant_id=t AND s.employee_id=e.id),'[]'),'attendance',COALESCE((SELECT jsonb_agg(to_jsonb(a)) FROM public.hr_attendance a WHERE a.tenant_id=t AND a.employee_id=e.id),'[]'),'terms',COALESCE((SELECT jsonb_agg(to_jsonb(x)) FROM public.hr_employment_terms x WHERE x.tenant_id=t AND x.employee_id=e.id),'[]'),'leave',COALESCE((SELECT jsonb_agg(to_jsonb(l)||jsonb_build_object('leave_type',to_jsonb(k))) FROM public.hr_leave_balances l JOIN public.hr_leave_types k ON k.id=l.leave_type_id WHERE l.tenant_id=t AND l.employee_id=e.id),'[]'),'requests',COALESCE((SELECT jsonb_agg(to_jsonb(r)||jsonb_build_object('leave_type',to_jsonb(k))) FROM public.hr_leave_requests r JOIN public.hr_leave_types k ON k.id=r.leave_type_id WHERE r.tenant_id=t AND r.employee_id=e.id),'[]'),'ledger',COALESCE((SELECT jsonb_agg(to_jsonb(l)||jsonb_build_object('leave_type',to_jsonb(k))) FROM public.hr_leave_ledger l JOIN public.hr_leave_types k ON k.id=l.leave_type_id WHERE l.tenant_id=t AND l.employee_id=e.id),'[]'),'holidays',COALESCE((SELECT jsonb_agg(to_jsonb(h)) FROM public.hr_holidays h WHERE h.tenant_id=t),'[]'),'swaps','[]','payroll','[]');END $$;
REVOKE ALL ON FUNCTION public.rota_my_work_context(uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.rota_my_work_context(uuid) TO authenticated;